      "category": "concept"
    },
    {
      "name": "线性变换",
      "aliases": ["linear transformation", "线性映射"],
      "definition_snippet": "满足加法和数乘保持的映射 T: V → W。",
      "category": "concept"
    },
    {
      "name": "加法保持",
      "aliases": ["additivity", "加法性"],
      "definition_snippet": "T(α + β) = T(α) + T(β)。",
      "category": "property"
    },
