      "category": "concept"
    },
    {
      "name": "坐标",
      "aliases": ["coordinates", "坐标向量"],
      "definition_snippet": "T(α_j) 在 W 的基下的坐标构成矩阵列。",
      "category": "concept"
    },
    {
      "name": "矩阵",
      "aliases": ["matrix", "变换矩阵"],
      "definition_snippet": "用来表示线性变换的 m×n 矩阵 A。",
      "category": "concept"
    },
    {
      "name": "线性变换的矩阵表示",
      "aliases": ["matrix representation of linear transformation", "矩阵表示"],
      "definition_snippet": "选定基后线性变换可用矩阵 A 表示。",
      "category": "concept"
    },
    {
      "name": "核",
      "aliases": ["kernel", "Ker(T)"],
      "definition_snippet": "Ker(T) = {α ∈ V | T(α) = 0}。",
      "category": "concept"
    },
    {
      "name": "零空间",
      "aliases": ["null space", "零子空间"],
      "definition_snippet": "核对应的零空间。",
      "category": "concept"
    },
    {
      "name": "像",
      "aliases": ["image", "像空间"],
      "definition_snippet": "Im(T) = {T(α) | α ∈ V}。",
      "category": "concept"
    },
    {
      "name": "列空间",
      "aliases": ["column space", "像的列空间"],
      "definition_snippet": "像对应的列空间。",
      "category": "concept"
    },
    {
      "name": "维数",
      "aliases": ["dimension", "维度"],
      "definition_snippet": "核、像或向量空间的维数。",
      "category": "concept"
    },
    {
      "name": "秩-零度定理",
      "aliases": ["rank-nullity theorem", "维数定理"],
      "definition_snippet": "dim(Ker(T)) + dim(Im(T)) = dim(V)。",
      "category": "theorem"
    },
    {
      "name": "线性变换的复合",
      "aliases": ["composition of linear transformations", "复合变换"],
      "definition_snippet": "S∘T: U → W 也是线性变换。",
      "category": "operation"
    },
    {
      "name": "线性变换的逆",
      "aliases": ["inverse linear transformation", "逆变换"],
      "definition_snippet": "若 T 可逆，则 T⁻¹ 也是线性变换。",
      "category": "operation"
    },
    {
      "name": "可逆线性变换",
      "aliases": ["invertible linear transformation", "可逆线性映射"],
      "definition_snippet": "存在逆映射的线性变换。",
      "category": "concept"
    },
    {
      "name": "矩阵乘法",
      "aliases": ["matrix multiplication", "矩阵相乘"],
      "definition_snippet": "线性变换复合对应矩阵乘法 BA。",
      "category": "operation"
    },
    {
      "name": "特征值",
      "aliases": ["eigenvalue", "特征标量"],
      "definition_snippet": "线性变换的固有性质，不依赖基的选择。",
      "category": "concept"
    },
    {
      "name": "基的选择",
